INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3050, 'glad', '/ɡlæd/', 'adjective', '{"zh-TW":["高興的"],"en":["feeling pleasure and happiness"]}', NULL, 'glad to help / glad to hear', '[{"en":"I am glad to help you with this.","zh-TW":"我很樂意幫你處理這件事。"},{"en":"I am glad to hear the good news.","zh-TW":"我很高興聽到好消息。"}]', '{"adjective":"glad","adverb":"gladly"}', NULL, 1, 3050, NULL),
(3051, 'glamping', '/''ɡlæmpɪŋ/', 'noun', '{"zh-TW":["豪華露營"],"en":["glamorous camping with comfortable amenities and accommodations"]}', NULL, 'go glamping / glamping site / glamping experience', '[{"en":"Glamping lets you enjoy nature without sacrificing comfort.","zh-TW":"豪華露營讓你在不犧牲舒適的情況下享受大自然。"},{"en":"The glamping resort offered heated tents with real beds and a hot tub.","zh-TW":"這個豪華露營度假村提供配有真正床鋪和熱水浴缸的加熱帳篷。"}]', NULL, NULL, 3, 3051, NULL),
(3052, 'glass', '/ɡlæs/', 'noun', '{"zh-TW":["玻璃；玻璃杯"],"en":["a hard transparent material","a container for drinking"]}', NULL, 'glass ceiling / glass of water', '[{"en":"Women still face the glass ceiling.","zh-TW":"女性仍面臨玻璃天花板效應。"},{"en":"Would you like a glass of water?","zh-TW":"你要一杯水嗎？"}]', '{"noun":"glass","adjective":"glassy"}', NULL, 2, 3052, NULL),
(3053, 'glaze', '/''ɡleɪz/', 'verb', '{"zh-TW":["給...上釉；上糖霜"],"en":["to coat food with a glossy substance such as a sauce, sugar syrup, or egg wash before or after cooking"]}', NULL, 'glaze with honey / glaze a pastry / glaze with egg wash', '[{"en":"She glazed the ham with a mixture of maple syrup and mustard.","zh-TW":"她用楓糖漿和芥末的混合物給火腿上了釉。"},{"en":"The pastry chef glazed the croissants with an egg wash for a golden finish.","zh-TW":"糕點師用蛋液給牛角麵包上了釉，使其呈現金黃色。"}]', '{"noun":"glaze"}', NULL, 2, 3053, NULL),
(3054, 'global', '/ˈɡloʊbəl/', 'adjective', '{"zh-TW":["全球的"],"en":["relating to the whole world"]}', NULL, 'global market/economy', '[{"en":"The company has a global presence.","zh-TW":"該公司在全球有業務。"},{"en":"Global trade continues to expand.","zh-TW":"全球貿易持續擴張。"}]', '{"noun":"globalization","adjective":"global","adverb":"globally"}', NULL, 2, 3054, 879),
(3055, 'global citizenship', '/''ɡləʊbəl ˌsɪtɪzənˌʃɪp/', 'noun', '{"zh-TW":["全球公民意識；世界公民精神"],"en":["the idea of belonging to a broader community beyond the nation-state, with a sense of responsibility to the world"]}', NULL, 'develop global citizenship / promote global citizenship / global citizenship education', '[{"en":"Global citizenship education encourages students to think beyond national borders.","zh-TW":"全球公民意識教育鼓勵學生超越國家邊界思考。"},{"en":"A sense of global citizenship motivates individuals to act on issues affecting all humanity.","zh-TW":"全球公民意識激勵個人就影響全人類的問題採取行動。"}]', '{"noun":"citizen","noun2":"citizenship"}', NULL, 5, 3055, NULL),
(3056, 'global reach', '/ˈɡloʊbəl riːtʃ/', 'noun', '{"zh-TW":["全球覆蓋；全球影響力"],"en":["the ability of a company to operate in or serve multiple countries"]}', NULL, 'expand global reach / leverage global reach', '[{"en":"The company expanded its global reach through an international partnership.","zh-TW":"公司通過國際夥伴關係擴大了其全球覆蓋。"},{"en":"Social media gives small businesses global reach at low cost.","zh-TW":"社群媒體讓小企業以低成本實現全球覆蓋。"}]', NULL, NULL, 4, 3056, NULL),
(3057, 'global sourcing', '/ˈɡloʊbəl ˈsɔːrsɪŋ/', 'noun', '{"zh-TW":["全球採購"],"en":["the strategy of finding and purchasing goods from suppliers worldwide"]}', NULL, 'implement global sourcing / global sourcing advantages', '[{"en":"Global sourcing allows companies to reduce costs by buying from low-cost markets.","zh-TW":"全球採購允許公司通過從低成本市場購買來降低成本。"},{"en":"Managing quality and logistics is a key challenge in global sourcing.","zh-TW":"管理品質和物流是全球採購的主要挑戰。"}]', NULL, NULL, 5, 3057, NULL),
(3058, 'global supply chain', '/ˈɡloʊbəl səˈplaɪ tʃeɪn/', 'noun', '{"zh-TW":["全球供應鏈"],"en":["a network of suppliers, manufacturers, and distributors across multiple countries"]}', NULL, 'manage a global supply chain / global supply chain risk', '[{"en":"Disruptions to the global supply chain affect companies worldwide.","zh-TW":"全球供應鏈的中斷影響了全球企業。"},{"en":"Managing a global supply chain requires coordination across time zones.","zh-TW":"管理全球供應鏈需要跨時區協調。"}]', NULL, NULL, 5, 3058, NULL),
(3059, 'global warming', '/ˈɡləʊbəl ˈwɔːrmɪŋ/', 'noun', '{"zh-TW":["全球暖化"],"en":["the gradual increase in the earth''s average temperature"]}', NULL, 'combat global warming / effects of global warming', '[{"en":"Global warming is melting polar ice caps.","zh-TW":"全球暖化正在融化極地冰帽。"},{"en":"Reducing greenhouse gas emissions is key to limiting global warming.","zh-TW":"減少溫室氣體排放是限制全球暖化的關鍵。"}]', '{"adjective":"global"}', NULL, 5, 3059, NULL),
(3060, 'globalization', '/ˌɡləʊbəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["全球化"],"en":["the process of international integration of economies and cultures"]}', NULL, 'economic globalization / effects of globalization', '[{"en":"Globalization has increased opportunities for international trade.","zh-TW":"全球化增加了國際貿易的機會。"},{"en":"Companies must adapt their strategies in response to globalization.","zh-TW":"企業必須調整策略以應對全球化。"}]', '{"verb":"globalize","adjective":"global"}', NULL, 5, 3060, NULL),
(3061, 'globetrotter', '/''ɡləʊbˌtrɒtər/', 'noun', '{"zh-TW":["環球旅行者；全球旅遊者"],"en":["a person who travels widely and frequently around the world"]}', NULL, 'seasoned globetrotter / frequent globetrotter', '[{"en":"As a globetrotter, she had visited more than ninety countries.","zh-TW":"作為一名環球旅行者，她走訪了九十多個國家。"},{"en":"The globetrotter shared his travel stories on a popular blog.","zh-TW":"這位環球旅行者在一個受歡迎的部落格上分享了他的旅行故事。"}]', NULL, NULL, 4, 3061, NULL),
(3062, 'gluten', '/''ɡluːtən/', 'noun', '{"zh-TW":["麩質；麵筋"],"en":["a protein mixture found in wheat and related grains, which causes issues for those with gluten intolerance"]}', NULL, 'gluten intolerance / gluten allergy / gluten-free diet', '[{"en":"People with celiac disease must completely avoid gluten in their diet.","zh-TW":"患有乳糜瀉的人必須完全避免飲食中的麩質。"},{"en":"The restaurant clearly marks which dishes contain gluten for allergy awareness.","zh-TW":"餐廳清楚標注哪些菜肴含有麩質，以提醒過敏者注意。"}]', '{"adjective":"gluten-free"}', NULL, 2, 3062, NULL),
(3063, 'gluten-free', '/ˌɡluːtən ˈfriː/', 'adjective', '{"zh-TW":["無麩質的"],"en":["containing no gluten"]}', NULL, 'gluten-free menu / gluten-free option', '[{"en":"We offer a gluten-free menu for sensitive guests.","zh-TW":"我們為敏感的賓客提供無麩質菜單。"},{"en":"Please request a gluten-free dish when making your reservation.","zh-TW":"訂位時請要求無麩質餐點。"}]', NULL, NULL, 4, 3063, NULL),
(3064, 'glycemic index', '/''ɡlaɪˌsiːmɪk ˈɪndeks/', 'noun', '{"zh-TW":["升糖指數；血糖生成指數"],"en":["a measure of how quickly foods cause blood sugar levels to rise"]}', NULL, 'low glycemic index / high glycemic index / glycemic index chart', '[{"en":"Oats have a low glycemic index, making them a good breakfast choice for diabetics.","zh-TW":"燕麥的升糖指數低，使其成為糖尿病患者的良好早餐選擇。"},{"en":"Foods with a high glycemic index can cause rapid spikes in blood sugar.","zh-TW":"升糖指數高的食物可能導致血糖迅速升高。"}]', NULL, NULL, 5, 3064, NULL),
(3065, 'go', 'ɡoʊ', 'verb', '{"zh-TW":["去；前往","進行"],"en":["to move to a place","to happen in a certain way"]}', NULL, 'go ahead/over budget', '[{"en":"Everything is going according to plan.","zh-TW":"一切都按計畫進行。"}]', NULL, NULL, 1, 3065, NULL),
(3066, 'go-live', '/ɡoʊ laɪv/', 'noun', '{"zh-TW":["上線；啟用"],"en":["the date when a system or product is made available to users"]}', NULL, 'go-live date / prepare for go-live / post go-live support', '[{"en":"The go-live was delayed by two weeks due to testing issues.","zh-TW":"由於測試問題，上線日期推遲了兩週。"},{"en":"Extensive training was provided before the system go-live.","zh-TW":"系統上線前提供了廣泛的培訓。"}]', '{"verb":"go live"}', NULL, 3, 3066, NULL),
(3067, 'go-to-market strategy', '/ɡoʊ tə ˈmɑːrkɪt ˈstrætədʒi/', 'noun', '{"zh-TW":["進入市場策略；上市策略"],"en":["a plan for launching a product or entering a new market"]}', NULL, 'develop a go-to-market strategy / execute the go-to-market strategy', '[{"en":"The go-to-market strategy focused on enterprise customers first.","zh-TW":"進入市場策略首先聚焦於企業客戶。"},{"en":"A strong go-to-market strategy is critical for product success.","zh-TW":"強大的上市策略對產品成功至關重要。"}]', '{"abbreviation":"GTM strategy"}', NULL, 5, 3067, NULL),
(3068, 'goal', 'ɡoʊl', 'noun', '{"zh-TW":["目標；目的","進球"],"en":["an aim or objective","a point scored in sport"]}', NULL, 'set a goal/achieve a goal', '[{"en":"The team set ambitious sales goals.","zh-TW":"團隊設定了雄心勃勃的銷售目標。"}]', '{"adjective":"goal-oriented"}', NULL, 1, 3068, NULL),
(3069, 'goal setting', '/ɡoʊl ˈsetɪŋ/', 'noun', '{"zh-TW":["目標設定"],"en":["the process of identifying and defining objectives to be achieved"]}', NULL, 'effective goal setting / goal setting framework', '[{"en":"Goal setting at the start of the year aligns teams on priorities.","zh-TW":"年初的目標設定使各團隊在優先事項上保持一致。"},{"en":"SMART goal setting makes objectives specific, measurable, and time-bound.","zh-TW":"SMART目標設定使目標具體、可衡量且有時限。"}]', NULL, NULL, 4, 3069, NULL),
(3070, 'going concern', '/ˈɡoʊɪŋ kənˈsɜːrn/', 'noun', '{"zh-TW":["持續經營假設"],"en":["the assumption that a business will continue to operate for the foreseeable future"]}', NULL, 'assess going concern / going concern assumption', '[{"en":"Auditors raised doubts about the company going concern status.","zh-TW":"審計師對公司的持續經營狀況提出了質疑。"},{"en":"Management confirmed the going concern assumption in the annual report.","zh-TW":"管理層在年度報告中確認了持續經營假設。"}]', NULL, NULL, 5, 3070, NULL),
(3071, 'going concern opinion', '/ˈɡoʊɪŋ kənˈsɜːrn əˈpɪnjən/', 'noun', '{"zh-TW":["持續經營意見"],"en":["an auditor''s statement questioning whether a company can continue to operate"]}', NULL, 'issue a going concern opinion / respond to a going concern opinion', '[{"en":"The auditor issued a going concern opinion due to ongoing losses.","zh-TW":"審計師因持續虧損而發表了持續經營意見。"},{"en":"Management must address the issues raised in a going concern opinion.","zh-TW":"管理層必須解決持續經營意見中提出的問題。"}]', NULL, NULL, 5, 3071, NULL),
(3072, 'going-private transaction', '/ˈɡoʊɪŋ ˈpraɪvɪt trænˈzækʃən/', 'noun', '{"zh-TW":["私有化交易"],"en":["the process by which a publicly listed company becomes a private entity"]}', NULL, 'complete a going-private transaction / going-private offer', '[{"en":"The founder initiated a going-private transaction to gain operational flexibility.","zh-TW":"創始人啟動了私有化交易以獲得運營靈活性。"},{"en":"A going-private transaction requires a premium offer to public shareholders.","zh-TW":"私有化交易需要向公眾股東提出溢價要約。"}]', '{"synonym":"privatization","synonym2":"take-private"}', NULL, 5, 3072, NULL),
(3073, 'gold', '/ɡoʊld/', 'noun', '{"zh-TW":["黃金；金色"],"en":["a precious yellow metal","something very valuable"]}', NULL, 'gold standard / gold medal', '[{"en":"This product is the gold standard.","zh-TW":"這個產品是黃金標準。"},{"en":"Gold prices rose sharply.","zh-TW":"金價大幅上漲。"}]', '{"noun":"gold","adjective":"golden"}', NULL, 1, 3073, NULL),
(3074, 'gold standard', '/ɡəʊld ˈstændərd/', 'noun', '{"zh-TW":["金本位制；黃金標準"],"en":["a monetary system backed by gold; a benchmark of excellence"]}', NULL, 'gold standard policy / abandon the gold standard / clinical gold standard', '[{"en":"Most countries abandoned the gold standard in the twentieth century, moving to fiat currencies.","zh-TW":"大多數國家在二十世紀放棄了金本位制，轉向法定貨幣。"},{"en":"Randomized controlled trials are the gold standard for measuring treatment effectiveness.","zh-TW":"隨機對照試驗是衡量治療有效性的黃金標準。"}]', NULL, NULL, 5, 3074, NULL),
(3075, 'good', 'ɡʊd', 'adjective', '{"zh-TW":["好的；優質的","擅長的"],"en":["of high quality","skilled at something"]}', NULL, 'good performance/good communication', '[{"en":"She has good communication skills.","zh-TW":"她有良好的溝通技巧。"}]', '{"noun":"goodness","adverb":"well"}', NULL, 1, 3075, NULL),
(3076, 'good faith', '/ɡʊd feɪθ/', 'noun', '{"zh-TW":["善意；誠信"],"en":["the intention to deal honestly and fairly with others"]}', NULL, 'act in good faith / good faith negotiations / good faith effort', '[{"en":"The parties negotiated the settlement in good faith.","zh-TW":"雙方以善意進行了和解談判。"},{"en":"Contracts require both parties to perform their obligations in good faith.","zh-TW":"合約要求雙方以誠信履行義務。"}]', NULL, NULL, 4, 3076, NULL),
(3077, 'goods', '/ɡʊdz/', 'noun', '{"zh-TW":["商品；貨物"],"en":["items for sale; merchandise"]}', NULL, 'consumer/manufactured goods', '[{"en":"The goods were shipped last week.","zh-TW":"貨物上週已發出。"},{"en":"Consumer goods make up 60% of our sales.","zh-TW":"消費品佔我們銷售額的60%。"}]', '{"noun":"goods"}', NULL, 2, 3077, NULL),
(3078, 'goodwill', '/ˈɡʊdwɪl/', 'noun', '{"zh-TW":["商譽"],"en":["the intangible value of a business beyond its physical assets"]}', NULL, 'goodwill impairment / recognize goodwill / goodwill amortization', '[{"en":"Goodwill on the balance sheet reflected the brand''s value.","zh-TW":"資產負債表上的商譽反映了品牌的價值。"},{"en":"An impairment charge was recorded against goodwill.","zh-TW":"針對商譽記錄了減值費用。"}]', NULL, NULL, 3, 3078, NULL),
(3079, 'goodwill amortization', '/ˈɡʊdwɪl əˌmɔːrtɪˈzeɪʃən/', 'noun', '{"zh-TW":["商譽攤銷"],"en":["the gradual reduction of goodwill recorded after an acquisition"]}', NULL, 'goodwill amortization period / annual goodwill amortization', '[{"en":"Goodwill amortization reduced the reported earnings by 5 million.","zh-TW":"商譽攤銷將報告盈利減少了500萬元。"},{"en":"Some accounting standards require goodwill amortization over 10 years.","zh-TW":"某些會計準則要求在10年內攤銷商譽。"}]', NULL, NULL, 5, 3079, NULL),
(3080, 'goodwill impairment', '/ˈɡʊdwɪl ɪmˈpeərmənt/', 'noun', '{"zh-TW":["商譽減損"],"en":["a reduction in the value of goodwill recorded on the balance sheet"]}', NULL, 'test for goodwill impairment / recognize goodwill impairment', '[{"en":"The annual goodwill impairment test resulted in a 20 million write-down.","zh-TW":"年度商譽減損測試導致了2000萬元的減記。"},{"en":"Goodwill impairment charges reduced the company reported earnings.","zh-TW":"商譽減損費用降低了公司的報告盈利。"}]', NULL, NULL, 5, 3080, NULL),
(3081, 'gourmet', '/ˈɡʊərmeɪ/', 'adjective', '{"zh-TW":["美食的；精緻的"],"en":["of a high quality or sophisticated standard"]}', NULL, 'gourmet restaurant / gourmet food', '[{"en":"The hotel''s gourmet restaurant has three Michelin stars.","zh-TW":"飯店的美食餐廳獲得了三顆米其林星。"},{"en":"They offer a gourmet tasting menu every weekend.","zh-TW":"他們每個週末提供精緻試菜菜單。"}]', '{"noun":"gourmet"}', NULL, 3, 3081, NULL),
(3082, 'govern', '/ˈɡʌvərn/', 'verb', '{"zh-TW":["治理；管理","統治；管理"],"en":["to control and direct public affairs; to regulate","to officially control a country or organization"]}', NULL, 'govern by rules/laws; govern a country / governing body', '[{"en":"The country is governed by a democratic system.","zh-TW":"該國由民主制度治理。"},{"en":"Clear rules govern the use of company assets.","zh-TW":"明確的規則管理公司資產的使用。"},{"en":"The country is governed by a president.","zh-TW":"這個國家由總統統治。"},{"en":"Laws govern how businesses operate.","zh-TW":"法律規範企業的營運方式。"}]', '{"noun":"government/governance/governor","verb":"govern","noun2":"governor","noun3":"governance"}', NULL, 2, 3082, 689),
(3083, 'governance', '/ˈɡʌvərnəns/', 'noun', '{"zh-TW":["治理；公司管治"],"en":["the system of rules and practices directing a company"]}', NULL, 'corporate governance / governance framework / good governance', '[{"en":"Strong corporate governance builds investor confidence.","zh-TW":"良好的公司治理建立投資者信心。"},{"en":"The governance structure was reviewed after the scandal.","zh-TW":"醜聞後，治理結構被重新審查。"}]', '{"verb":"govern","adjective":"governing"}', NULL, 4, 3083, 789),
(3084, 'governance framework', '/ˈɡʌvənəns ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["治理框架"],"en":["a structured set of policies and procedures for directing an organization"]}', NULL, 'establish a governance framework / governance framework review', '[{"en":"The new governance framework defined roles and accountability clearly.","zh-TW":"新治理框架清楚地定義了角色和問責制。"},{"en":"A robust governance framework is essential for publicly listed companies.","zh-TW":"強健的治理框架對於上市公司至關重要。"}]', NULL, NULL, 5, 3084, NULL),
(3085, 'governance structure', '/ˈɡʌvərnəns ˈstrʌktʃər/', 'noun', '{"zh-TW":["治理結構"],"en":["the framework defining authority, decision-making, and accountability in an organization"]}', NULL, 'establish a governance structure / governance structure review', '[{"en":"A clear governance structure ensures accountability at every level.","zh-TW":"清晰的治理結構確保了各個層面的問責制。"},{"en":"The board approved a new governance structure after the merger.","zh-TW":"董事會在合併後批准了新的治理結構。"}]', NULL, NULL, 5, 3085, NULL),
(3086, 'governing law', '/ˈɡʌvərnɪŋ lɔː/', 'noun', '{"zh-TW":["準據法；管轄法律"],"en":["the law that applies to interpret a contract"]}', NULL, 'governing law clause / choice of governing law', '[{"en":"The governing law for this contract is the law of New York.","zh-TW":"本合約的準據法為紐約州法律。"},{"en":"Both parties agreed on the governing law before signing.","zh-TW":"雙方在簽署前就準據法達成一致。"}]', NULL, NULL, 5, 3086, NULL),
(3087, 'government bond', '/ˈɡʌvərnmənt bɒnd/', 'noun', '{"zh-TW":["政府債券"],"en":["a debt security issued by a national government to finance public spending"]}', NULL, 'invest in government bonds / government bond yield', '[{"en":"Government bonds are considered the safest fixed income investments.","zh-TW":"政府債券被視為最安全的固定收益投資。"},{"en":"The yield on government bonds reflects expectations for inflation and growth.","zh-TW":"政府債券的殖利率反映了對通貨膨脹和增長的預期。"}]', '{"synonym":"sovereign bond","synonym2":"Treasury bond"}', NULL, 5, 3087, NULL),
(3088, 'government subsidy', '/ˈɡʌvənmənt ˈsʌbsɪdi/', 'noun', '{"zh-TW":["政府補貼；政府津貼"],"en":["financial aid provided by the government to support a specific industry or activity"]}', NULL, 'receive a government subsidy / government subsidy program', '[{"en":"The renewable energy sector received government subsidies to grow.","zh-TW":"可再生能源行業獲得了政府補貼以促進增長。"},{"en":"Government subsidies distort competition if not applied carefully.","zh-TW":"如果應用不當，政府補貼會扭曲競爭。"}]', NULL, NULL, 5, 3088, NULL),
(3089, 'GPA', '/dʒiː piː eɪ/', 'noun', '{"zh-TW":["學業成績平均點數"],"en":["Grade Point Average: a measure of academic performance"]}', NULL, 'maintain a high GPA / GPA requirement', '[{"en":"She maintained a 3.9 GPA throughout her undergraduate studies.","zh-TW":"她在整個本科學習期間保持了3.9的學業成績平均點數。"},{"en":"A high GPA increases your chances of graduate school admission.","zh-TW":"高學業成績平均點數提高了您被研究所錄取的機會。"}]', NULL, NULL, 1, 3089, NULL),
(3090, 'grace', '/ɡreɪs/', 'noun', '{"zh-TW":["寬限；優雅"],"en":["a period of extra time; elegance"]}', NULL, 'grace period', '[{"en":"There is a 30-day grace period for payment.","zh-TW":"有30天的寬限期付款。"},{"en":"She handled the crisis with grace.","zh-TW":"她優雅地處理了危機。"}]', '{"noun":"grace","adjective":"graceful/gracious"}', NULL, 2, 3090, NULL),
(3091, 'grace period', '/ɡreɪs ˌpɪəriəd/', 'noun', '{"zh-TW":["寬限期"],"en":["a period after a due date during which a payment can be made without penalty"]}', NULL, 'grant a grace period / within the grace period', '[{"en":"The lender granted a 15-day grace period on the late payment.","zh-TW":"貸款方對逾期付款給予了15天的寬限期。"},{"en":"Insurance policies include a grace period for premium payments.","zh-TW":"保險政策包含保費支付的寬限期。"}]', NULL, NULL, 4, 3091, NULL),
(3092, 'grace period interest', '/ɡreɪs ˈpɪəriəd ˈɪntrɪst/', 'noun', '{"zh-TW":["寬限期利息"],"en":["interest that accrues during a period when payments are deferred"]}', NULL, 'incur grace period interest / grace period interest waiver', '[{"en":"The borrower agreed to pay grace period interest at half the standard rate.","zh-TW":"借款人同意以標準利率的一半支付寬限期利息。"},{"en":"Grace period interest was waived as part of the debt restructuring deal.","zh-TW":"寬限期利息作為債務重組協議的一部分被豁免了。"}]', NULL, NULL, 5, 3092, NULL),
(3093, 'grade', '/ɡreɪd/', 'noun / verb', '{"zh-TW":["等級；評分","成績；年級"],"en":["a level of quality; to assess performance","a mark showing how good work is"]}', NULL, 'high/top grade; get good grades / grade point average', '[{"en":"The product is available in different grades.","zh-TW":"產品有不同的等級。"},{"en":"Papers were graded by the instructor.","zh-TW":"報告由講師評分。"},{"en":"She always gets good grades.","zh-TW":"她總是拿好成績。"},{"en":"He''s in the fifth grade.","zh-TW":"他讀五年級。"}]', '{"noun":"grade/grading","verb":"grade","noun2":"grading"}', NULL, 2, 3093, NULL),
(3094, 'grade inflation', '/''ɡreɪd ɪnˌfleɪʃən/', 'noun', '{"zh-TW":["成績膨脹；分數通貨膨脹"],"en":["a general increase in student grades without a corresponding increase in student achievement"]}', NULL, 'combat grade inflation / grade inflation problem / grade inflation controversy', '[{"en":"Critics argue that grade inflation has reduced the value of academic degrees.","zh-TW":"批評者認為，成績膨脹降低了學術學位的價值。"},{"en":"The university implemented stricter grading policies to address the problem of grade inflation.","zh-TW":"大學實施了更嚴格的評分政策，以解決成績膨脹問題。"}]', '{"verb":"inflate","noun":"inflation"}', NULL, 5, 3094, NULL),
(3095, 'grade point average', '/''ɡreɪd pɔɪnt ˌævərɪdʒ/', 'noun', '{"zh-TW":["平均成績；GPA"],"en":["a number representing the average value of the accumulated final grades earned in all courses"]}', NULL, 'maintain a high grade point average / calculate grade point average / GPA requirement', '[{"en":"Many employers ask for your grade point average as part of the job application.","zh-TW":"許多雇主在招聘申請中要求提供你的平均成績。"},{"en":"She maintained a grade point average of 3.8 throughout her undergraduate studies.","zh-TW":"她在整個大學本科學習期間保持了3.8的平均成績。"}]', NULL, NULL, 5, 3095, NULL),
(3096, 'gradient descent', '/ˈɡreɪdiənt dɪˈsent/', 'noun', '{"zh-TW":["梯度下降"],"en":["an optimization algorithm that iteratively adjusts parameters to minimize loss"]}', NULL, 'apply gradient descent / gradient descent optimization / stochastic gradient descent', '[{"en":"Gradient descent is the core optimization algorithm in machine learning.","zh-TW":"梯度下降是機器學習中的核心優化算法。"},{"en":"Stochastic gradient descent updates weights using individual data samples.","zh-TW":"隨機梯度下降使用單個數據樣本更新權重。"}]', NULL, NULL, 5, 3096, NULL),
(3097, 'grading rubric', '/''ɡreɪdɪŋ ˌruːbrɪk/', 'noun', '{"zh-TW":["評分標準；評分規準"],"en":["a scoring guide used to evaluate student work based on defined criteria"]}', NULL, 'use a grading rubric / follow the grading rubric / create a grading rubric', '[{"en":"The professor distributed a grading rubric so students knew exactly what was expected.","zh-TW":"教授分發了評分標準，讓學生確切知道期望是什麼。"},{"en":"A clear grading rubric promotes consistency and transparency in student assessment.","zh-TW":"清晰的評分標準在學生評量中促進了一致性和透明度。"}]', NULL, NULL, 5, 3097, NULL),
(3098, 'gradual', '/ˈɡrædʒuəl/', 'adjective', '{"zh-TW":["逐漸的"],"en":["happening slowly over time"]}', NULL, 'gradual increase/improvement', '[{"en":"There has been a gradual improvement in sales.","zh-TW":"銷售有了逐漸的改善。"},{"en":"The transition will be gradual.","zh-TW":"轉型將是漸進的。"}]', '{"adjective":"gradual","adverb":"gradually"}', NULL, 3, 3098, 880),
(3099, 'graduate', '/''ɡrædʒuːɪt/', 'noun', '{"zh-TW":["大學畢業生；研究生"],"en":["a person who has completed a course of study, especially in higher education"]}', NULL, 'recent graduate / college graduate / graduate student', '[{"en":"As a recent graduate, she was eager to apply her knowledge in the workplace.","zh-TW":"作為一名應屆畢業生，她急切地想在職場上應用她的知識。"},{"en":"Graduate students are expected to conduct original research in their field.","zh-TW":"研究生被期望在其領域進行原創研究。"}]', '{"verb":"graduate","adjective":"graduate"}', NULL, 3, 3099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3100, 'graduate school', '/''ɡrædʒuɪt skuːl/', 'noun', '{"zh-TW":["研究生院"],"en":["a university department offering postgraduate degrees such as master''s and doctoral programs"]}', NULL, 'apply to graduate school / attend graduate school / graduate school admission', '[{"en":"She applied to three graduate schools and was accepted by her top choice.","zh-TW":"她申請了三所研究生院，並被她的首選學校錄取。"},{"en":"Graduate school requires a higher level of independent thinking than undergraduate study.","zh-TW":"研究生院比大學本科學習需要更高程度的獨立思考能力。"}]', NULL, NULL, 5, 3100, NULL),
(3101, 'graduation', '/ˌɡrædʒuˈeɪʃən/', 'noun', '{"zh-TW":["畢業；畢業典禮"],"en":["the ceremony of receiving a degree"]}', NULL, 'graduation ceremony / after graduation', '[{"en":"Her parents came to her graduation.","zh-TW":"她的父母來參加她的畢業典禮。"},{"en":"What will you do after graduation?","zh-TW":"畢業後你打算做什麼？"}]', '{"verb":"graduate","noun2":"graduate"}', NULL, 4, 3101, NULL),
(3102, 'grant', '/ɡrænt/', 'noun / verb', '{"zh-TW":["撥款；授予"],"en":["money given for a purpose; to give formally"]}', NULL, 'research/government grant', '[{"en":"The university received a research grant.","zh-TW":"大學獲得了研究撥款。"},{"en":"Permission was granted to proceed.","zh-TW":"已批准繼續進行。"}]', '{"noun":"grant","verb":"grant"}', NULL, 2, 3102, 690),
(3103, 'grant funding', '/ɡrɑːnt ˈfʌndɪŋ/', 'noun', '{"zh-TW":["補助資金；撥款"],"en":["non-repayable money awarded by a government or organization for a specific purpose"]}', NULL, 'apply for grant funding / secure grant funding', '[{"en":"The startup secured grant funding for its renewable energy project.","zh-TW":"初創企業為其可再生能源項目獲得了補助資金。"},{"en":"Grant funding from the government supported the community development plan.","zh-TW":"政府的補助資金支持了社區發展計劃。"}]', NULL, NULL, 5, 3103, NULL),
(3104, 'grant period', '/ɡrɑːnt ˌpɪəriəd/', 'noun', '{"zh-TW":["補助期間"],"en":["the duration during which a grant is active and eligible for expenditure"]}', NULL, 'within the grant period / extend the grant period', '[{"en":"All project activities must be completed within the grant period.","zh-TW":"所有項目活動必須在補助期間內完成。"},{"en":"The grant period was extended to allow for construction delays.","zh-TW":"補助期間因施工延誤而延長了。"}]', NULL, NULL, 4, 3104, NULL),
(3105, 'grant proposal', '/''ɡrɑːnt prəˌpəʊzəl/', 'noun', '{"zh-TW":["補助金申請；研究計畫書"],"en":["a formal written request for funding submitted to a grant-making organization"]}', NULL, 'write a grant proposal / submit a grant proposal / competitive grant proposal', '[{"en":"She spent weeks preparing a grant proposal for research funding.","zh-TW":"她花了幾週時間準備研究資助的補助金申請。"},{"en":"A successful grant proposal clearly explains the research goals and expected outcomes.","zh-TW":"成功的補助金申請清楚地解釋了研究目標和預期成果。"}]', NULL, NULL, 5, 3105, NULL),
(3106, 'granular', '/ˈɡrænjʊlər/', 'adjective', '{"zh-TW":["細粒度的；詳細的"],"en":["relating to fine detail; highly specific"]}', NULL, 'granular data / granular analysis / granular level', '[{"en":"Granular data allows more precise identification of market trends.","zh-TW":"細粒度數據允許更精確地識別市場趨勢。"},{"en":"The report provides a granular breakdown of costs by department.","zh-TW":"報告提供了按部門劃分的細粒度成本分解。"}]', '{"noun":"granularity","adverb":"granularly"}', NULL, 3, 3106, NULL),
(3107, 'grasp', '/ɡræsp/', 'verb / noun', '{"zh-TW":["掌握；理解"],"en":["to seize; to understand"]}', NULL, 'grasp a concept/opportunity', '[{"en":"She quickly grasped the concept.","zh-TW":"她很快掌握了這個概念。"},{"en":"Success is within our grasp.","zh-TW":"成功在我們的掌握之中。"}]', '{"noun":"grasp","verb":"grasp"}', NULL, 2, 3107, NULL),
(3108, 'grateful', '/ˈɡreɪtfəl/', 'adjective', '{"zh-TW":["感激的"],"en":["feeling thankful","feeling or showing thanks"]}', '{"root":{"text":"grat","meaning":"pleasing (令人愉悅)"},"suffix":{"text":"-ful","meaning":"full of (充滿)"},"logic":"充滿感謝之情的。"}', 'grateful for/to; grateful for / deeply grateful', '[{"en":"We are grateful for your continued support.","zh-TW":"我們感謝您持續的支持。"},{"en":"I would be grateful if you could reply promptly.","zh-TW":"如果您能及時回覆，我將不勝感激。"},{"en":"I''m grateful for your help.","zh-TW":"我很感激你的幫助。"},{"en":"She was deeply grateful to her mentor.","zh-TW":"她對她的導師深懷感激。"}]', '{"noun":"gratitude","adjective":"grateful","adverb":"gratefully"}', NULL, 3, 3108, NULL),
(3109, 'gratuitous', '/''ɡrəˈtjuːɪtəs/', 'adjective', '{"zh-TW":["無緣無故的；不必要的"],"en":["uncalled for; lacking good reason; unwarranted"]}', NULL, 'gratuitous comment / gratuitous content / gratuitous criticism', '[{"en":"His gratuitous criticism of the proposal demoralized the entire team.","zh-TW":"他對提案無緣無故的批評使整個團隊士氣低落。"},{"en":"The report was criticized for including gratuitous details that distracted from the main findings.","zh-TW":"報告因包含分散主要發現注意力的不必要細節而受到批評。"}]', '{"adverb":"gratuitously","noun":"gratuity"}', NULL, 4, 3109, NULL),
(3110, 'gratuity', '/ɡrəˈtjuːɪti/', 'noun', '{"zh-TW":["小費；服務費"],"en":["a sum of money given as a tip for service"]}', NULL, 'add a gratuity / include gratuity', '[{"en":"A 15% gratuity is automatically added to the bill.","zh-TW":"帳單自動加收15%服務費。"},{"en":"It is customary to leave a gratuity for good service.","zh-TW":"留下小費給優質服務是一種習慣。"}]', '{"verb":"gratify","adjective":"gratuitous"}', NULL, 3, 3110, NULL),
(3111, 'grave', '/ɡreɪv/', 'adjective', '{"zh-TW":["嚴重的；嚴肅的"],"en":["serious; giving cause for concern"]}', NULL, 'grave concern/consequences', '[{"en":"This is a matter of grave concern.","zh-TW":"這是一件令人嚴重關切的事。"},{"en":"The error could have grave consequences.","zh-TW":"這個錯誤可能有嚴重的後果。"}]', '{"noun":"gravity","adjective":"grave","adverb":"gravely"}', NULL, 2, 3111, NULL),
(3112, 'great', 'ɡreɪt', 'adjective', '{"zh-TW":["偉大的；很好的","重要的"],"en":["very large or important","excellent"]}', NULL, 'great idea/great opportunity', '[{"en":"This is a great opportunity for growth.","zh-TW":"這是一個很好的增長機會。"}]', '{"noun":"greatness","adverb":"greatly"}', NULL, 2, 3112, NULL),
(3113, 'green', '/ɡriːn/', 'adjective', '{"zh-TW":["綠色的；環保的"],"en":["the color of grass","environmentally friendly"]}', NULL, 'go green / green energy', '[{"en":"Our company decided to go green.","zh-TW":"我們公司決定走環保路線。"},{"en":"We invest in green energy projects.","zh-TW":"我們投資綠色能源專案。"}]', '{"adjective":"green","noun":"green","noun2":"greenhouse"}', NULL, 2, 3113, NULL),
(3114, 'green building', '/ɡriːn ˈbɪldɪŋ/', 'noun', '{"zh-TW":["綠色建築"],"en":["a building designed to reduce its environmental impact"]}', NULL, 'construct a green building / green building certification', '[{"en":"The new office complex is certified as a green building.","zh-TW":"新辦公大樓獲得了綠色建築認證。"},{"en":"Green buildings use less energy and water than conventional ones.","zh-TW":"綠色建築比傳統建築使用更少的能源和水。"}]', NULL, NULL, 5, 3114, NULL),
(3115, 'green certification', '/ɡriːn ˌsɜːrtɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["綠色認證"],"en":["an official recognition of meeting environmental standards"]}', NULL, 'obtain green certification / green certification process', '[{"en":"The building achieved LEED green certification.","zh-TW":"這棟大樓獲得了LEED綠色認證。"},{"en":"Green certification demonstrates a company''s commitment to sustainability.","zh-TW":"綠色認證展示了公司對永續發展的承諾。"}]', NULL, NULL, 5, 3115, NULL),
(3116, 'green infrastructure', '/ɡriːn ˈɪnfrəstrʌktʃər/', 'noun', '{"zh-TW":["綠色基礎設施"],"en":["natural or semi-natural elements integrated into urban planning"]}', NULL, 'develop green infrastructure / urban green infrastructure / green infrastructure benefits', '[{"en":"Green infrastructure such as parks and wetlands reduces urban flooding.","zh-TW":"公園和濕地等綠色基礎設施減少了城市洪水。"},{"en":"Cities invest in green infrastructure to improve resilience to climate change.","zh-TW":"城市投資綠色基礎設施以提高應對氣候變化的韌性。"}]', NULL, NULL, 5, 3116, NULL),
(3117, 'green technology', '/ɡriːn tɛkˈnɒlədʒi/', 'noun', '{"zh-TW":["綠色技術；環保技術"],"en":["technology aimed at reducing environmental harm"]}', NULL, 'invest in green technology / green technology innovation', '[{"en":"Green technology is driving the clean energy revolution.","zh-TW":"綠色技術正在推動清潔能源革命。"},{"en":"The company invested in green technology to cut its emissions.","zh-TW":"公司投資了綠色技術以減少排放量。"}]', NULL, NULL, 5, 3117, NULL),
(3118, 'greenhouse effect', '/ˈɡriːnhaʊs ɪˈfekt/', 'noun', '{"zh-TW":["溫室效應"],"en":["the trapping of heat in the atmosphere by greenhouse gases"]}', NULL, 'enhanced greenhouse effect / greenhouse effect mechanism / reduce greenhouse effect', '[{"en":"The greenhouse effect is intensified by rising CO₂ concentrations.","zh-TW":"溫室效應因CO₂濃度上升而加劇。"},{"en":"Understanding the greenhouse effect is fundamental to climate science.","zh-TW":"理解溫室效應是氣候科學的基礎。"}]', NULL, NULL, 5, 3118, NULL),
(3119, 'greenhouse gas', '/ˈɡriːnhaʊs ɡæs/', 'noun', '{"zh-TW":["溫室氣體"],"en":["a gas that traps heat in the atmosphere"]}', NULL, 'reduce greenhouse gas emissions / greenhouse gas target', '[{"en":"CO2 is the most common greenhouse gas produced by humans.","zh-TW":"二氧化碳是人類產生的最常見溫室氣體。"},{"en":"Reducing greenhouse gas emissions requires global cooperation.","zh-TW":"減少溫室氣體排放需要全球合作。"}]', NULL, NULL, 5, 3119, NULL),
(3120, 'greenhouse gas emissions', '/''ɡriːnˌhaʊs ɡæs ɪˌmɪʃənz/', 'noun', '{"zh-TW":["溫室氣體排放"],"en":["gases released into the atmosphere that trap heat and contribute to global warming"]}', NULL, 'reduce greenhouse gas emissions / greenhouse gas emissions target / measure greenhouse gas emissions', '[{"en":"International agreements aim to reduce greenhouse gas emissions to limit global temperature rise.","zh-TW":"國際協議旨在減少溫室氣體排放，以限制全球氣溫上升。"},{"en":"Transportation and electricity generation are the largest sources of greenhouse gas emissions.","zh-TW":"交通和發電是溫室氣體排放的最大來源。"}]', '{"noun2":"emissions","adjective":"greenhouse"}', NULL, 5, 3120, NULL),
(3121, 'greenwashing', '/ˈɡriːnwɒʃɪŋ/', 'noun', '{"zh-TW":["漂綠；偽裝環保"],"en":["making misleading claims about the environmental benefits of products or practices"]}', NULL, 'accuse of greenwashing / greenwashing accusations / avoid greenwashing', '[{"en":"The company was accused of greenwashing after its sustainability claims were exposed as exaggerated.","zh-TW":"公司的永續性聲明被揭露為誇大其詞後，被指控漂綠。"},{"en":"Regulators are cracking down on greenwashing in investment marketing.","zh-TW":"監管機構正在打擊投資營銷中的漂綠行為。"}]', '{"verb":"greenwash"}', NULL, 4, 3121, NULL),
(3122, 'greeting', 'ˈɡriːtɪŋ', 'noun', '{"zh-TW":["問候；招呼","祝賀"],"en":["a way of addressing someone","words used to welcome"]}', NULL, 'formal greeting/season''s greetings', '[{"en":"A warm greeting sets the tone.","zh-TW":"熱情的問候定下基調。"}]', '{"verb":"greet","adjective":"greeting"}', NULL, 3, 3122, NULL),
(3123, 'grievance', '/ˈɡriːvəns/', 'noun', '{"zh-TW":["申訴；不滿"],"en":["a formal complaint by an employee about a workplace issue"]}', NULL, 'file a grievance / grievance procedure / handle grievances', '[{"en":"She filed a grievance against her manager for unfair treatment.","zh-TW":"她就不公平對待向主管提出申訴。"},{"en":"The company has a formal grievance procedure for employees.","zh-TW":"公司有正式的員工申訴程序。"}]', '{"verb":"grieve","adjective":"aggrieved"}', NULL, 3, 3123, NULL),
(3124, 'grievance procedure', '/ˈɡriːvəns prəˈsiːdʒər/', 'noun', '{"zh-TW":["申訴程序；投訴程序"],"en":["a formal process for employees to raise workplace complaints and have them addressed"]}', NULL, 'follow the grievance procedure / initiate a grievance procedure', '[{"en":"Employees must follow the grievance procedure before escalating to external bodies.","zh-TW":"員工在上升至外部機構之前必須遵循申訴程序。"},{"en":"The HR team handled the complaint through the standard grievance procedure.","zh-TW":"HR團隊通過標準申訴程序處理了投訴。"}]', NULL, NULL, 5, 3124, NULL),
(3125, 'gross', '/ɡroʊs/', 'adjective / noun', '{"zh-TW":["總的；毛額"],"en":["total before deductions; very obvious"]}', NULL, 'gross income/profit', '[{"en":"Gross revenue reached $10 million.","zh-TW":"總收入達到1000萬美元。"},{"en":"The gross profit margin improved.","zh-TW":"毛利率有所改善。"}]', '{"noun":"gross","adjective":"gross"}', NULL, 2, 3125, NULL),
(3126, 'gross domestic product', '/ɡrəʊs dəˈmɛstɪk ˈprɒdʌkt/', 'noun', '{"zh-TW":["國內生產總值"],"en":["the total value of goods and services produced in a country"]}', NULL, 'grow gross domestic product / gross domestic product data', '[{"en":"The country''s gross domestic product grew by 3% last year.","zh-TW":"該國的國內生產總值去年增長了3%。"},{"en":"Gross domestic product is the primary measure of national economic output.","zh-TW":"國內生產總值是衡量國家經濟產出的主要指標。"}]', '{"abbreviation":"GDP"}', NULL, 5, 3126, NULL),
(3127, 'gross margin', '/ɡrəʊs ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["毛利率"],"en":["the percentage of revenue remaining after the cost of goods sold"]}', NULL, 'calculate gross margin / improve gross margin', '[{"en":"The company''s gross margin improved after renegotiating supplier contracts.","zh-TW":"重新談判供應商合約後，公司的毛利率有所提升。"},{"en":"A gross margin above 50% is strong for a software business.","zh-TW":"對軟體業務來說，超過50%的毛利率表現強勁。"}]', NULL, NULL, 4, 3127, NULL),
(3128, 'gross margin analysis', '/ɡroʊs ˈmɑːrdʒɪn əˈnæləsɪs/', 'noun', '{"zh-TW":["毛利率分析"],"en":["the examination of gross profit margins across products, segments, or periods"]}', NULL, 'conduct gross margin analysis / gross margin analysis findings', '[{"en":"Gross margin analysis revealed that electronics had the highest profitability.","zh-TW":"毛利率分析顯示電子產品的盈利能力最高。"},{"en":"The CFO presented a gross margin analysis at the board review.","zh-TW":"財務長在董事會審查時提交了毛利率分析。"}]', NULL, NULL, 5, 3128, NULL),
(3129, 'gross profit', '/ɡroʊs ˈprɒfɪt/', 'noun', '{"zh-TW":["毛利"],"en":["revenue minus the direct costs of producing goods or services"]}', NULL, 'gross profit margin / calculate gross profit', '[{"en":"Gross profit improved due to lower raw material costs.","zh-TW":"由於原材料成本降低，毛利有所改善。"},{"en":"The gross profit margin reached 45% last quarter.","zh-TW":"毛利率上季達到45%。"}]', '{"adjective":"gross"}', NULL, 4, 3129, NULL),
(3130, 'gross profit margin', '/ɡroʊs ˈprɒfɪt ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["毛利率"],"en":["revenue minus cost of goods sold, expressed as a percentage of revenue"]}', NULL, 'calculate gross profit margin / improve gross profit margin', '[{"en":"The new pricing strategy increased the gross profit margin to 45%.","zh-TW":"新的定價策略將毛利率提高到了45%。"},{"en":"A declining gross profit margin may indicate rising production costs.","zh-TW":"下降的毛利率可能表明生產成本上升。"}]', NULL, NULL, 5, 3130, NULL),
(3131, 'gross redemption yield', '/ɡrəʊs rɪˈdempʃən jiːld/', 'noun', '{"zh-TW":["總贖回收益率"],"en":["the total return on a bond if held to maturity, before taxes"]}', NULL, 'calculate gross redemption yield / compare gross redemption yield / higher gross redemption yield', '[{"en":"The gross redemption yield on the ten-year bond is four percent.","zh-TW":"十年期債券的總贖回收益率為百分之四。"},{"en":"Gross redemption yield is useful for comparing bonds of different maturities.","zh-TW":"總贖回收益率有助於比較不同到期日的債券。"}]', NULL, NULL, 5, 3131, NULL),
(3132, 'gross revenue', '/ɡroʊs ˈrevɪnjuː/', 'noun', '{"zh-TW":["總收入；毛收入"],"en":["total income before any deductions"]}', NULL, 'calculate gross revenue / increase gross revenue', '[{"en":"Gross revenue reached 100 million for the first time.","zh-TW":"總收入首次達到了1億元。"},{"en":"Gross revenue figures are reported before returns and discounts.","zh-TW":"總收入數字在退貨和折扣前報告。"}]', NULL, NULL, 5, 3132, NULL),
(3133, 'ground', '/ɡraʊnd/', 'noun', '{"zh-TW":["【主要意義-名詞】地面；土地","【次要意義-動詞】擱置；禁止（飛機）起飛","【次要意義-動詞】教導基礎；使打好根基","【次要意義-名詞（複數）】理由；根據；依據"],"en":["[primary - noun] the surface of the earth","[secondary - verb] to keep an aircraft from flying; to confine to one place","[secondary - verb] to teach someone the basic principles of a subject","[secondary - plural noun] a reason or justification for something"]}', NULL, 'grounds for dismissal / well-grounded / ground floor / break new ground / on the grounds that', '[{"en":"All flights were grounded due to the severe weather conditions.","zh-TW":"由於惡劣天氣，所有航班被迫停飛。"},{"en":"The dismissal was challenged on the grounds that proper procedures were not followed.","zh-TW":"解雇被以未遵守適當程序為由提出異議。"},{"en":"New employees are grounded in company policy during their first week.","zh-TW":"新員工在第一週接受公司政策的基礎培訓。"}]', '{"noun":"groundwork, groundbreaking","adjective":"grounded"}', 'grounds（複數）= 「理由/根據」（grounds for dismissal = 解雇理由），on the grounds that（以……為由），動詞 ground = 「擱置/打基礎」均是 TOEIC 法律和人事文章的必考用法。', 2, 3133, NULL),
(3134, 'ground crew', '/ɡraʊnd kruː/', 'noun', '{"zh-TW":["地勤人員"],"en":["workers who maintain and service aircraft on the ground"]}', NULL, 'experienced ground crew / ground crew services', '[{"en":"The ground crew prepared the aircraft for departure.","zh-TW":"地勤人員為飛機出發做好了準備。"},{"en":"Ground crew worked efficiently to turn around the flight.","zh-TW":"地勤人員高效地完成了飛機的周轉。"}]', NULL, NULL, 4, 3134, NULL),
(3135, 'ground floor', '/ɡraʊnd flɔːr/', 'noun', '{"zh-TW":["底層；基礎"],"en":["the floor of a building at street level; also used metaphorically for early participation"]}', NULL, 'get in on the ground floor / ground floor apartment', '[{"en":"Investors who got in on the ground floor saw huge returns.","zh-TW":"在基礎階段進入的投資者獲得了豐厚回報。"},{"en":"The ground floor retail units command the highest rents.","zh-TW":"底層零售單位要求最高的租金。"}]', NULL, NULL, 4, 3135, NULL),
(3136, 'ground lease', '/''ɡraʊnd liːs/', 'noun', '{"zh-TW":["地基租約；地皮租約"],"en":["a long-term lease under which the lessee can use the land for a specified period"]}', NULL, 'enter a ground lease / ground lease terms / benefit of ground lease', '[{"en":"The developer signed a ninety-nine-year ground lease for the commercial property.","zh-TW":"開發商為商業房產簽署了九十九年的地基租約。"},{"en":"A ground lease allows developers to construct buildings on land they do not own.","zh-TW":"地基租約允許開發商在他們不擁有的土地上建設建築物。"}]', NULL, NULL, 4, 3136, NULL),
(3137, 'ground transportation', '/ɡraʊnd ˌtrænsˌpɔːrˈteɪʃən/', 'noun', '{"zh-TW":["地面交通"],"en":["transportation on the ground between locations"]}', NULL, 'arrange ground transportation / ground transportation options', '[{"en":"The hotel provides free ground transportation from the airport.","zh-TW":"飯店提供機場免費地面交通接送。"},{"en":"Ground transportation is available at exit B.","zh-TW":"B出口有地面交通工具。"}]', NULL, NULL, 5, 3137, NULL),
(3138, 'groundbreaking', '/ˈɡraʊndˌbreɪkɪŋ/', 'adjective', '{"zh-TW":["開創性的；突破性的"],"en":["innovative; introducing new methods or discoveries"]}', NULL, 'groundbreaking research / groundbreaking technology / groundbreaking study', '[{"en":"The groundbreaking study transformed our understanding of genetic inheritance.","zh-TW":"這項開創性的研究改變了我們對遺傳學的理解。"},{"en":"The firm won awards for its groundbreaking approach to sustainable architecture.","zh-TW":"該公司因其可持續建築的開創性方法而獲獎。"}]', NULL, NULL, 5, 3138, NULL),
(3139, 'grounded', '/ˈɡraʊndɪd/', 'adjective', '{"zh-TW":["有根基的；基於…的"],"en":["well established or based on a firm foundation; sensible and realistic"]}', NULL, 'grounded theory / grounded approach / grounded in evidence', '[{"en":"Her recommendation is grounded in solid empirical research.","zh-TW":"她的建議基於紮實的實證研究。"},{"en":"A grounded theory approach allows themes to emerge from data.","zh-TW":"紮根理論方法允許主題從數據中浮現。"}]', NULL, NULL, 3, 3139, NULL),
(3140, 'grounding', '/ˈɡraʊndɪŋ/', 'noun', '{"zh-TW":["基礎；根基"],"en":["a basis of knowledge, experience, or principle"]}', NULL, 'theoretical grounding / empirical grounding / strong grounding', '[{"en":"A strong grounding in statistics is essential for data analysis.","zh-TW":"數據分析需要紮實的統計學基礎。"},{"en":"The course provides grounding in all major research methodologies.","zh-TW":"課程提供所有主要研究方法論的基礎。"}]', NULL, NULL, 3, 3140, NULL),
(3141, 'groundwater depletion', '/ˈɡraʊndwɔːtər dɪˈpliːʃən/', 'noun', '{"zh-TW":["地下水耗竭"],"en":["the excessive extraction of underground water resources"]}', NULL, 'address groundwater depletion / groundwater depletion crisis / monitor groundwater depletion', '[{"en":"Over-irrigation has led to severe groundwater depletion in many arid regions.","zh-TW":"過度灌溉導致許多乾旱地區嚴重的地下水耗竭。"},{"en":"Groundwater depletion threatens long-term water security for farming communities.","zh-TW":"地下水耗竭威脅著農業社區的長期水資源安全。"}]', NULL, NULL, 5, 3141, NULL),
(3142, 'group', 'ɡruːp', 'noun', '{"zh-TW":["群組；小組","集團"],"en":["a number of people or things together","a set of companies"]}', NULL, 'work group/focus group', '[{"en":"The project team is a cross-functional group.","zh-TW":"專案團隊是一個跨職能小組。"}]', '{"verb":"group","adjective":"group-based"}', NULL, 2, 3142, NULL),
(3143, 'group dynamics', '/ɡruːp daɪˈnæmɪks/', 'noun', '{"zh-TW":["群體動態；團隊動力"],"en":["the interactions and processes within a group that influence its behavior"]}', NULL, 'understand group dynamics / improve group dynamics', '[{"en":"Positive group dynamics lead to higher team productivity.","zh-TW":"積極的群體動態帶來了更高的團隊生產力。"},{"en":"The facilitator worked to improve group dynamics during the workshop.","zh-TW":"主持人在研討會期間努力改善群體動態。"}]', NULL, NULL, 5, 3143, NULL),
(3144, 'group performance', '/ɡruːp pəˈfɔːrməns/', 'noun', '{"zh-TW":["集團業績；整體績效"],"en":["the financial results of a parent company and all its subsidiaries combined"]}', NULL, 'review group performance / group performance report', '[{"en":"Group performance improved 12% year on year.","zh-TW":"集團業績同比提升了12%。"},{"en":"The annual report consolidates group performance across all regions.","zh-TW":"年報整合了所有地區的集團業績。"}]', NULL, NULL, 5, 3144, NULL),
(3145, 'group project', '/''ɡruːp ˌprɒdʒekt/', 'noun', '{"zh-TW":["小組作業；團隊項目"],"en":["a collaborative task assigned to a group of students to complete together"]}', NULL, 'work on a group project / group project deadline / assign a group project', '[{"en":"The group project required all members to contribute equally to the research.","zh-TW":"小組作業要求所有成員對研究平等地做出貢獻。"},{"en":"She learned valuable teamwork skills through completing group projects at university.","zh-TW":"她通過在大學完成小組作業學到了寶貴的團隊合作技能。"}]', NULL, NULL, 5, 3145, NULL),
(3146, 'group reservation', '/ɡruːp ˌrɛzərˈveɪʃən/', 'noun', '{"zh-TW":["團體預訂"],"en":["a booking for a large number of rooms"]}', NULL, 'manage a group reservation / group reservation discount', '[{"en":"The conference required a group reservation of 50 rooms.","zh-TW":"會議需要預訂50間房的團體訂房。"},{"en":"Group reservations typically qualify for special discounted rates.","zh-TW":"團體預訂通常可享有特別折扣價。"}]', NULL, NULL, 5, 3146, NULL),
(3147, 'grow', '/ɡroʊ/', 'verb', '{"zh-TW":["成長；增加"],"en":["to increase in size or number","to develop"]}', NULL, 'grow rapidly / grow a business', '[{"en":"The company has grown rapidly.","zh-TW":"公司快速成長。"},{"en":"We plan to grow our customer base.","zh-TW":"我們計畫擴大客戶群。"}]', '{"verb":"grow","noun":"growth","adjective":"growing"}', NULL, 1, 3147, NULL),
(3148, 'growth', 'ɡroʊθ', 'noun', '{"zh-TW":["增長；成長","發展"],"en":["an increase in size or amount","development"]}', NULL, 'economic growth/business growth', '[{"en":"The company reported 15% annual growth.","zh-TW":"公司報告了15%的年增長率。"}]', '{"verb":"grow","adjective":"growing","adverb":"growingly"}', NULL, 2, 3148, NULL),
(3149, 'growth mindset', '/''ɡrəʊθ ˌmaɪndset/', 'noun', '{"zh-TW":["成長型思維；成長心態"],"en":["the belief that one''s abilities and intelligence can be developed through dedication and hard work"]}', NULL, 'develop a growth mindset / have a growth mindset / importance of a growth mindset', '[{"en":"Teaching students to have a growth mindset helps them embrace challenges as opportunities.","zh-TW":"教導學生擁有成長型思維有助於他們將挑戰視為機遇。"},{"en":"A growth mindset leads to greater perseverance and higher achievement over time.","zh-TW":"成長型思維隨著時間的推移帶來更大的堅持和更高的成就。"}]', '{"noun":"mindset","adjective":"growth-oriented"}', NULL, 5, 3149, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3150, 'growth potential', '/ɡroʊθ pəˈtenʃəl/', 'noun', '{"zh-TW":["增長潛力"],"en":["the capacity of a business or market to expand in size or revenue"]}', NULL, 'assess growth potential / high growth potential', '[{"en":"The emerging market segment has significant growth potential.","zh-TW":"新興市場細分具有顯著的增長潛力。"},{"en":"The startup''s growth potential attracted venture capital investment.","zh-TW":"新創公司的增長潛力吸引了創業投資。"}]', NULL, NULL, 5, 3150, NULL),
(3151, 'growth rate', '/ɡroʊθ reɪt/', 'noun', '{"zh-TW":["增長率"],"en":["the pace at which something increases over a period"]}', NULL, 'annual growth rate / compound growth rate / GDP growth rate', '[{"en":"The company achieved a compound annual growth rate of 15%.","zh-TW":"公司實現了15%的複合年增長率。"},{"en":"GDP growth rate slowed to 2% amid global uncertainties.","zh-TW":"在全球不確定性中，GDP增長率放緩至2%。"}]', NULL, NULL, 4, 3151, NULL),
(3152, 'GST', '/ˌdʒiː es ˈtiː/', 'noun', '{"zh-TW":["商品及服務稅"],"en":["goods and services tax; a broad-based tax on most goods and services"]}', NULL, 'collect GST / GST invoice / GST registration / GST refund', '[{"en":"GST of 10% is applied to most goods and services.","zh-TW":"大多數商品和服務適用10%的商品及服務稅。"},{"en":"The company applied for a GST refund on business inputs.","zh-TW":"公司申請了商業投入的商品及服務稅退稅。"}]', '{"full form":"goods and services tax"}', NULL, 1, 3152, NULL),
(3153, 'guarantee', '/ˌɡærənˈtiː/', 'noun / verb', '{"zh-TW":["保證；擔保"],"en":["a formal promise; to give a guarantee","a promise that something will be done or will happen"]}', '{"root":{"text":"garant","meaning":"warrant (擔保)"},"logic":"給予擔保的承諾。"}', 'money-back guarantee; money-back guarantee / under guarantee', '[{"en":"The product comes with a two-year guarantee.","zh-TW":"產品附有兩年保固。"},{"en":"We guarantee delivery within 48 hours.","zh-TW":"我們保證48小時內送達。"},{"en":"The product comes with a two-year guarantee.","zh-TW":"該產品附有兩年保固。"},{"en":"There is no guarantee of success.","zh-TW":"沒有成功的保證。"}]', '{"noun":"guarantee/guarantor","verb":"guarantee"}', NULL, 3, 3153, 366),
(3154, 'guarantee fee', '/ˌɡærənˈtiː fiː/', 'noun', '{"zh-TW":["擔保費"],"en":["a fee paid to the guarantor for providing a guarantee on a loan or contract"]}', NULL, 'charge a guarantee fee / guarantee fee rate', '[{"en":"The parent company charged a guarantee fee for backing the subsidiary loan.","zh-TW":"母公司因為子公司貸款提供擔保而收取了擔保費。"},{"en":"The guarantee fee was set at 0.5% of the facility amount annually.","zh-TW":"擔保費定為每年設施金額的0.5%。"}]', NULL, NULL, 5, 3154, NULL),
(3155, 'guarantee fund', '/ˌɡærənˈtiː fʌnd/', 'noun', '{"zh-TW":["保障基金；擔保基金"],"en":["a reserve fund set aside to compensate for defaults or financial failures"]}', NULL, 'establish a guarantee fund / draw from the guarantee fund', '[{"en":"The government established a guarantee fund to protect bank depositors.","zh-TW":"政府建立了一個保障基金以保護銀行存款人。"},{"en":"Exporters benefit from a guarantee fund that covers buyer payment defaults.","zh-TW":"出口商受益於涵蓋買方付款違約的擔保基金。"}]', NULL, NULL, 5, 3155, NULL),
(3156, 'guarantee period', '/ˌɡærənˈtiː ˌpɪəriəd/', 'noun', '{"zh-TW":["保固期；保證期"],"en":["the time during which a product or service is covered by a guarantee"]}', NULL, 'within the guarantee period / extend the guarantee period', '[{"en":"The defect was discovered within the two-year guarantee period.","zh-TW":"在兩年保固期內發現了缺陷。"},{"en":"Customers can claim a replacement within the guarantee period.","zh-TW":"客戶可以在保固期內申請更換。"}]', NULL, NULL, 5, 3156, NULL),
(3157, 'guarantor', '/ˌɡærənˈtɔːr/', 'noun', '{"zh-TW":["擔保人"],"en":["a person or organization that agrees to be responsible for another''s debt or obligation"]}', NULL, 'provide a guarantor / act as guarantor', '[{"en":"The parent company acted as guarantor for the subsidiary''s bank loan.","zh-TW":"母公司為子公司的銀行貸款充當了擔保人。"},{"en":"A personal guarantor can be held liable if the business defaults on the loan.","zh-TW":"如果企業無法償還貸款，個人擔保人可能需要承擔責任。"}]', '{"verb":"guarantee","noun":"guarantee"}', NULL, 3, 3157, NULL),
(3158, 'guess', '/ɡɛs/', 'verb', '{"zh-TW":["猜測"],"en":["to estimate without certain knowledge"]}', NULL, 'I guess / rough guess', '[{"en":"I guess we need more time.","zh-TW":"我想我們需要更多時間。"},{"en":"At a rough guess, it costs about $5000.","zh-TW":"粗略估計大約要5000美元。"}]', '{"verb":"guess","noun":"guess","noun2":"guesswork"}', NULL, 2, 3158, NULL),
(3159, 'guest speaker', '/ɡɛst ˈspiːkər/', 'noun', '{"zh-TW":["特邀演講者；嘉賓講者"],"en":["a person invited to speak at an event"]}', NULL, 'invite a guest speaker / guest speaker presentation', '[{"en":"A renowned economist served as the guest speaker at the summit.","zh-TW":"一位知名經濟學家擔任峰會的特邀演講者。"},{"en":"The guest speaker shared insights from her 20 years of experience.","zh-TW":"特邀演講者分享了她20年經驗的見解。"}]', NULL, NULL, 5, 3159, NULL),
(3160, 'guesthouse', '/''ɡestˌhaʊs/', 'noun', '{"zh-TW":["賓館；招待所"],"en":["a small privately run establishment offering bed and breakfast"]}', NULL, 'family guesthouse / local guesthouse / charming guesthouse', '[{"en":"The guesthouse had only six rooms, each decorated with local art.","zh-TW":"這家賓館只有六個房間，每間都用本地藝術品裝飾。"},{"en":"We preferred the intimate atmosphere of a guesthouse over a large hotel.","zh-TW":"我們更喜歡賓館的溫馨氛圍，勝過大型飯店。"}]', NULL, NULL, 4, 3160, NULL),
(3161, 'guidance', 'ˈɡaɪdəns', 'noun', '{"zh-TW":["指導；建議","方向"],"en":["advice or instructions","direction provided"]}', NULL, 'professional guidance/seek guidance', '[{"en":"Please seek guidance from your supervisor.","zh-TW":"請向您的主管尋求指導。"}]', '{"verb":"guide","adjective":"guided"}', NULL, 3, 3161, 367),
(3162, 'guide', '/ɡaɪd/', 'noun / verb', '{"zh-TW":["指南；引導"],"en":["a book of information; to direct or influence"]}', NULL, 'user guide / guide + 人 + through', '[{"en":"The manual serves as a guide for new employees.","zh-TW":"手冊作為新員工的指南。"},{"en":"She guided the team through the transition.","zh-TW":"她引導團隊度過了轉型期。"}]', '{"noun":"guide/guidance","verb":"guide"}', NULL, 2, 3162, NULL),
(3163, 'guided meditation', '/''ɡaɪdɪd ˌmedɪˈteɪʃən/', 'noun', '{"zh-TW":["引導冥想"],"en":["a form of meditation led by a teacher or recording, often done in wellness retreats"]}', NULL, 'practice guided meditation / guided meditation session', '[{"en":"The wellness retreat started each morning with a guided meditation session.","zh-TW":"健康靜修所每天早上以引導冥想課程開始。"},{"en":"Guided meditation apps have made it easier to develop a regular practice.","zh-TW":"引導冥想應用程式使建立定期練習變得更容易。"}]', NULL, NULL, 5, 3163, NULL),
(3164, 'guided tour', '/''ɡaɪdɪd tʊər/', 'noun', '{"zh-TW":["導覽行程；有嚮導的旅遊"],"en":["a tour of a place conducted by a guide who provides commentary and information"]}', NULL, 'book a guided tour / join a guided tour / private guided tour', '[{"en":"The guided tour of the ancient ruins lasted about two hours.","zh-TW":"古遺跡的導覽行程持續了大約兩個小時。"},{"en":"A guided tour is the best way to learn about the history of a new city.","zh-TW":"導覽行程是了解新城市歷史的最佳方式。"}]', NULL, NULL, 4, 3164, NULL),
(3165, 'guideline', '/ˈɡaɪdlaɪn/', 'noun', '{"zh-TW":["準則；指導方針"],"en":["a general rule or piece of advice"]}', NULL, 'follow/establish guidelines', '[{"en":"Please follow the company guidelines.","zh-TW":"請遵循公司準則。"},{"en":"New guidelines were issued for remote work.","zh-TW":"發布了遠端工作的新指導方針。"}]', '{"noun":"guideline"}', NULL, 3, 3165, 129),
(3166, 'guidelines', '/ˈɡaɪdlaɪnz/', 'noun', '{"zh-TW":["指導方針；準則"],"en":["rules or instructions providing direction"]}', NULL, 'follow guidelines / company guidelines', '[{"en":"Please follow the company guidelines when completing the form.","zh-TW":"填寫表格時請遵循公司指導方針。"},{"en":"New employees receive a copy of the workplace guidelines.","zh-TW":"新員工會收到一份工作場所準則副本。"}]', NULL, NULL, 4, 3166, NULL),
(3167, 'gut health', '/''ɡʌt helθ/', 'noun', '{"zh-TW":["腸道健康"],"en":["the state of the gastrointestinal tract and its microbial community, which affects overall health"]}', NULL, 'improve gut health / gut health supplement / affect gut health', '[{"en":"A diet rich in fiber and probiotics supports gut health significantly.","zh-TW":"富含纖維和益生菌的飲食對腸道健康有顯著的支持作用。"},{"en":"Scientists are discovering more links between gut health and mental well-being.","zh-TW":"科學家正在發現腸道健康與心理健康之間越來越多的聯繫。"}]', '{"adjective":"gut-friendly"}', NULL, 4, 3167, NULL),
(3168, 'gym', '/dʒɪm/', 'noun', '{"zh-TW":["健身房；體育館"],"en":["a place for physical exercise"]}', NULL, 'go to the gym / gym membership', '[{"en":"I go to the gym three times a week.","zh-TW":"我一週去健身房三次。"},{"en":"The gym has new equipment.","zh-TW":"健身房有新設備。"}]', NULL, NULL, 1, 3168, NULL),
(3169, 'gym equipment', '/''dʒɪm ɪˌkwɪpmənt/', 'noun', '{"zh-TW":["健身器材；健身房設備"],"en":["the machines and tools found in a fitness facility for exercise"]}', NULL, 'use gym equipment / gym equipment maintenance / purchase gym equipment', '[{"en":"The gym was fully equipped with modern gym equipment including treadmills and weights.","zh-TW":"健身房配備了包括跑步機和啞鈴在內的現代健身器材。"},{"en":"She learned how to use the gym equipment properly from a certified trainer.","zh-TW":"她從一位認證教練那裡學會了如何正確使用健身器材。"}]', NULL, NULL, 5, 3169, NULL),
(3170, 'gymnastics', '/''dʒɪmˈnæstɪks/', 'noun', '{"zh-TW":["體操；競技體操"],"en":["a sport involving physical exercises requiring balance, strength, flexibility, agility, and coordination"]}', NULL, 'compete in gymnastics / practice gymnastics / artistic gymnastics', '[{"en":"She started gymnastics at age four and competed nationally by age ten.","zh-TW":"她四歲開始練體操，十歲時就在全國比賽中出賽。"},{"en":"Rhythmic gymnastics combines elements of dance and gymnastics.","zh-TW":"藝術體操結合了舞蹈和體操的元素。"}]', '{"noun":"gymnast","adjective":"gymnastic"}', NULL, 4, 3170, NULL),
(3171, 'gynecology', '/ˌɡaɪnɪˈkɒlədʒi/', 'noun', '{"zh-TW":["婦科學；婦產科"],"en":["the branch of medicine dealing with female reproductive health"]}', NULL, 'gynecology appointment / gynecology specialist', '[{"en":"Regular gynecology checkups are important for women''s health.","zh-TW":"定期婦科檢查對女性健康很重要。"},{"en":"She was referred to a gynecology specialist for further evaluation.","zh-TW":"她被轉介到婦科專科醫生做進一步評估。"}]', '{"noun":"gynecologist","adjective":"gynecological"}', NULL, 4, 3171, NULL),
(3172, 'habit', '/ˈhæbɪt/', 'noun', '{"zh-TW":["習慣"],"en":["a regular behavior that is hard to stop"]}', NULL, 'bad habit / form a habit', '[{"en":"Develop good work habits early.","zh-TW":"及早養成良好的工作習慣。"},{"en":"It takes 21 days to form a habit.","zh-TW":"養成一個習慣需要21天。"}]', '{"noun":"habit","adjective":"habitual","adverb":"habitually"}', NULL, 2, 3172, NULL),
(3173, 'habitat', '/ˈhæbɪtæt/', 'noun', '{"zh-TW":["棲息地；居住環境"],"en":["the natural home of an animal or plant"]}', NULL, 'natural habitat / wildlife habitat', '[{"en":"Deforestation destroys the habitat of many species.","zh-TW":"砍伐森林破壞了許多物種的棲息地。"},{"en":"The wetlands provide habitat for migratory birds.","zh-TW":"濕地為候鳥提供了棲息地。"}]', '{"noun":"habitat, habitation","verb":"inhabit"}', NULL, 3, 3173, NULL),
(3174, 'habitat fragmentation', '/ˈhæbɪtæt ˌfræɡmənˈteɪʃən/', 'noun', '{"zh-TW":["棲息地碎片化"],"en":["the process by which large habitats are divided into smaller, isolated patches"]}', NULL, 'habitat fragmentation effects / prevent habitat fragmentation / habitat fragmentation and biodiversity', '[{"en":"Habitat fragmentation isolates animal populations and reduces genetic diversity.","zh-TW":"棲息地碎片化使動物種群隔離並降低遺傳多樣性。"},{"en":"Road construction is a major cause of habitat fragmentation in forests.","zh-TW":"道路建設是森林棲息地碎片化的主要原因。"}]', NULL, NULL, 5, 3174, NULL),
(3175, 'habitat loss', '/ˈhæbɪtæt lɒs/', 'noun', '{"zh-TW":["棲地喪失"],"en":["the destruction of environments where wildlife lives"]}', NULL, 'prevent habitat loss / habitat loss rate', '[{"en":"Habitat loss is the leading cause of biodiversity decline.","zh-TW":"棲地喪失是生物多樣性下降的主要原因。"},{"en":"Urban development often leads to significant habitat loss.","zh-TW":"城市開發往往導致嚴重的棲地喪失。"}]', NULL, NULL, 4, 3175, NULL),
(3176, 'hack', '/hæk/', 'verb', '{"zh-TW":["駭入；破解"],"en":["to gain unauthorized access to a computer"]}', NULL, 'hack into / life hack', '[{"en":"Someone hacked into the system.","zh-TW":"有人駭入了系統。"},{"en":"Here''s a useful life hack.","zh-TW":"這裡有一個實用的生活小技巧。"}]', '{"noun":"hacker","noun2":"hacking"}', NULL, 1, 3176, NULL),
(3177, 'hail', '/heɪl/', 'noun', '{"zh-TW":["冰雹"],"en":["pellets of frozen rain falling from clouds"]}', '{"root":{"text":"hail","meaning":"hailstone (冰雹)"},"logic":"指從雲中落下的冰粒。"}', 'hailstorm / hail damage', '[{"en":"The hail damaged several cars in the parking lot.","zh-TW":"冰雹損壞了停車場的幾輛車。"},{"en":"A sudden hailstorm caught everyone off guard.","zh-TW":"突如其來的冰雹讓所有人措手不及。"}]', '{"noun":"hailstorm"}', NULL, 1, 3177, NULL),
(3178, 'hair', '/hɛr/', 'noun', '{"zh-TW":["頭髮；毛髮"],"en":["the thin threads growing on the head"]}', NULL, 'hairstyle / hair salon', '[{"en":"She got a new hairstyle for the event.","zh-TW":"她為活動換了新髮型。"},{"en":"There is a hair salon downstairs.","zh-TW":"樓下有一間美髮沙龍。"}]', '{"noun":"hair","adjective":"hairy","noun2":"hairstyle"}', NULL, 1, 3178, NULL),
(3179, 'haircut', '/ˈheərkʌt/', 'noun', '{"zh-TW":["打折；折扣（金融）"],"en":["a percentage reduction applied to an asset''s value for collateral or risk purposes"]}', NULL, 'apply a haircut / steep haircut / regulatory haircut', '[{"en":"The central bank applied a ten percent haircut to mortgage collateral.","zh-TW":"中央銀行對抵押品施加了百分之十的折扣。"},{"en":"Lenders impose haircuts to protect against falling collateral values.","zh-TW":"貸款方施加折扣以防範抵押品價值下降。"}]', NULL, NULL, 3, 3179, NULL),
(3180, 'halal', '/həˈlɑːl/', 'adjective', '{"zh-TW":["清真的；合乎伊斯蘭教規的"],"en":["permissible according to Islamic law"]}', NULL, 'halal food / halal certified', '[{"en":"The restaurant serves halal food for Muslim guests.","zh-TW":"餐廳為穆斯林賓客提供清真食物。"},{"en":"Please indicate if you need a halal meal on the booking form.","zh-TW":"預訂表格上請說明是否需要清真餐食。"}]', NULL, NULL, 2, 3180, NULL),
(3181, 'half', '/hæf/', 'noun', '{"zh-TW":["一半"],"en":["one of two equal parts"]}', NULL, 'half price / first half', '[{"en":"The item is half price today.","zh-TW":"這個商品今天半價。"},{"en":"Revenue grew in the first half of the year.","zh-TW":"上半年營收成長了。"}]', '{"noun":"half","adjective":"half"}', NULL, 1, 3181, NULL),
(3182, 'half board', '/''hɑːf bɔːrd/', 'noun', '{"zh-TW":["半食宿；提供早晚餐的住宿方式"],"en":["hotel accommodation including breakfast and one other meal, typically dinner"]}', NULL, 'half board package / book on half board / half board rate', '[{"en":"We chose half board so we could go out for lunch each day.","zh-TW":"我們選擇了半食宿，這樣我們每天都可以外出吃午餐。"},{"en":"The half board option provided breakfast and dinner but not lunch.","zh-TW":"半食宿選項提供早餐和晚餐，但不包括午餐。"}]', NULL, NULL, 4, 3182, NULL),
(3183, 'hallmark', '/''hɔːlmɑːrk/', 'noun', '{"zh-TW":["標誌；特質；特徵"],"en":["a distinctive feature or characteristic, especially one of excellence"]}', NULL, 'hallmark of quality / hallmark of success / hallmark of professionalism', '[{"en":"Attention to detail is the hallmark of a skilled craftsperson.","zh-TW":"對細節的關注是技藝精湛工匠的標誌。"},{"en":"Transparency and accountability are the hallmarks of good governance.","zh-TW":"透明度和問責制是良好治理的標誌。"}]', '{"adjective":"hallmark"}', NULL, 3, 3183, NULL),
(3184, 'halt', '/hɔːlt/', 'verb, noun', '{"zh-TW":["停止；中止","暫停"],"en":["to stop or cause to stop","a temporary stop"]}', NULL, 'come to a halt / halt production', '[{"en":"The project was halted due to budget cuts.","zh-TW":"該項目因預算削減而停止。"},{"en":"Traffic came to a halt during the storm.","zh-TW":"暴風雨期間交通完全停止。"}]', '{"noun":"halt","verb":"halt"}', NULL, 1, 3184, NULL),
(3185, 'hamper', '/ˈhæmpər/', 'verb', '{"zh-TW":["妨礙；阻礙"],"en":["to prevent someone from easily doing something"]}', NULL, 'hamper progress/efforts/growth', '[{"en":"Bad weather hampered rescue efforts.","zh-TW":"惡劣天氣妨礙了救援工作。"},{"en":"Lack of funding hampered the research.","zh-TW":"缺乏資金阻礙了研究進展。"}]', '{"noun":"hamper","verb":"hamper"}', NULL, 2, 3185, NULL),
(3186, 'hand', '/hænd/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】手","【次要意義-動詞】傳遞；遞給","【次要意義-名詞】幫助；協助（a hand）","【次要意義-名詞】工人；勞動者"],"en":["[primary - noun] the body part at the end of the arm","[secondary - verb] to pass or give something to someone","[secondary - noun] help or assistance","[secondary - noun] a worker or employee, especially in manual work"]}', NULL, 'hand in / hand out / lend a hand / give someone a hand / first-hand / at hand', '[{"en":"Could you hand me the report that was submitted this morning?","zh-TW":"你能把今早提交的報告遞給我嗎？"},{"en":"All staff are required to hand in their reports by Friday.","zh-TW":"所有員工須在週五前繳交報告。"},{"en":"The warehouse hired extra hands to manage the holiday rush.","zh-TW":"倉庫僱用了額外的人手來應對假日旺季。"}]', '{"noun":"handout, handover, handbook","adjective":"hands-on"}', 'hand 作動詞表「遞交/傳遞」，hand in（繳交），hand out（分發），名詞 hand（工人/幫手）、first-hand（第一手的）均是 TOEIC 職場文章常見詞彙。', 1, 3186, NULL),
(3187, 'hand luggage', '/hænd ˈlʌɡɪdʒ/', 'noun', '{"zh-TW":["手提行李"],"en":["small bags taken into the cabin of an aircraft"]}', NULL, 'hand luggage limit / hand luggage restrictions', '[{"en":"Your hand luggage must fit under the seat or overhead bin.","zh-TW":"您的手提行李必須放在座位下方或頭頂置物箱中。"},{"en":"Each passenger is allowed one piece of hand luggage.","zh-TW":"每位乘客可攜帶一件手提行李。"}]', NULL, NULL, 4, 3187, NULL),
(3188, 'handbook', '/ˈhændbʊk/', 'noun', '{"zh-TW":["手冊；指南"],"en":["a book giving useful information or instructions"]}', NULL, 'employee handbook / reference handbook', '[{"en":"Please read the employee handbook before your first day.","zh-TW":"請在第一天上班前閱讀員工手冊。"},{"en":"The handbook covers all safety procedures.","zh-TW":"手冊涵蓋了所有安全程序。"}]', '{"noun":"handbook"}', NULL, 3, 3188, NULL),
(3189, 'handle', '/ˈhændl/', 'verb, noun', '{"zh-TW":["處理；應對","把手；手柄"],"en":["to deal with a situation","a part of an object designed to be held"]}', NULL, 'handle a situation/complaint/task', '[{"en":"She handled the crisis with great composure.","zh-TW":"她非常鎮定地處理了這場危機。"},{"en":"Please handle the package with care.","zh-TW":"請小心搬運這個包裹。"}]', '{"noun":"handler, handling","verb":"handle"}', NULL, 2, 3189, 130),
(3190, 'handout', '/ˈhændaʊt/', 'noun', '{"zh-TW":["講義；資料單"],"en":["a document distributed to participants in a meeting or class"]}', NULL, 'distribute handouts / prepare handouts', '[{"en":"The trainer prepared handouts summarizing the key points.","zh-TW":"培訓師準備了總結關鍵要點的講義。"},{"en":"Please review the handout before the session begins.","zh-TW":"請在課程開始前查看講義。"}]', NULL, NULL, 3, 3190, NULL),
(3191, 'handover', '/ˈhændˌoʊvər/', 'noun', '{"zh-TW":["移交；交接"],"en":["the transfer of responsibility from one person to another"]}', NULL, 'project handover / job handover / smooth handover', '[{"en":"A detailed handover document was prepared for the incoming manager.","zh-TW":"為接任的管理者準備了詳細的交接文件。"},{"en":"The handover of the project took two weeks to complete.","zh-TW":"項目的移交花了兩週時間完成。"}]', '{"verb":"hand over"}', NULL, 3, 3191, 881),
(3192, 'hands-on', 'hændz ɒn', 'adjective', '{"zh-TW":["實際操作的；動手的","親身參與的"],"en":["involving practical work","learning by doing"]}', NULL, 'hands-on experience/hands-on training', '[{"en":"This role requires hands-on experience.","zh-TW":"這個職位需要實際操作經驗。"}]', '{"adverb":"hands-on"}', NULL, 3, 3192, NULL),
(3193, 'happen', '/ˈhæpən/', 'verb', '{"zh-TW":["發生"],"en":["to take place; to occur"]}', NULL, 'happen to / what happened', '[{"en":"What happened at the meeting?","zh-TW":"會議上發生了什麼？"},{"en":"This should not happen again.","zh-TW":"這不應該再發生。"}]', '{"verb":"happen","noun":"happening"}', NULL, 2, 3193, NULL),
(3194, 'happy', '/ˈhæpi/', 'adjective', '{"zh-TW":["快樂的；滿意的"],"en":["feeling pleasure","satisfied"]}', NULL, 'happy to help / happy with', '[{"en":"I am happy to assist you.","zh-TW":"我很樂意協助你。"},{"en":"Are you happy with the result?","zh-TW":"你對結果滿意嗎？"}]', '{"adjective":"happy","noun":"happiness","adverb":"happily","adjective2":"unhappy"}', NULL, 2, 3194, NULL),
(3195, 'harass', '/həˈræs/', 'verb', '{"zh-TW":["騷擾；煩擾"],"en":["to subject to aggressive pressure or intimidation"]}', NULL, 'harass someone / sexually harass', '[{"en":"Employees who harass others will face disciplinary action.","zh-TW":"騷擾他人的員工將面臨紀律處分。"},{"en":"She was harassed by persistent sales calls.","zh-TW":"她被持續不斷的推銷電話所騷擾。"}]', '{"noun":"harassment","verb":"harass"}', NULL, 2, 3195, NULL),
(3196, 'harassment', '/həˈræsmənt/', 'noun', '{"zh-TW":["騷擾；煩擾"],"en":["aggressive pressure or intimidation"]}', NULL, 'sexual harassment / workplace harassment', '[{"en":"The company has a strict policy against workplace harassment.","zh-TW":"公司有嚴格的反職場騷擾政策。"},{"en":"She filed a complaint about harassment.","zh-TW":"她提出了騷擾投訴。"}]', '{"noun":"harassment","verb":"harass"}', NULL, 4, 3196, NULL),
(3197, 'harbor', '/ˈhɑːrbər/', 'noun, verb', '{"zh-TW":["港口；海港","懷有（想法或感覺）"],"en":["a sheltered area of water for ships","to hold a thought or feeling secretly"]}', NULL, 'harbor doubts/resentment', '[{"en":"The ship docked at the harbor.","zh-TW":"船停靠在港口。"},{"en":"She harbored doubts about the plan.","zh-TW":"她對這個計劃心存疑慮。"}]', '{"noun":"harbor","verb":"harbor"}', NULL, 2, 3197, NULL),
(3198, 'hard', '/hɑːrd/', 'adjective', '{"zh-TW":["【主要意義-形容詞】硬的；困難的","【次要意義-副詞】努力地；猛烈地；使勁地","【次要意義-形容詞】確鑿的；嚴厲的"],"en":["[primary - adjective] solid and firm; difficult","[secondary - adverb] with great effort or force","[secondary - adjective] definite and reliable; stern"]}', NULL, 'work hard / hard evidence / hard currency / hard sell / hard on the heels', '[{"en":"The team worked hard to meet the production deadline.","zh-TW":"團隊努力工作以趕上生產截止日期。"},{"en":"Hard evidence is needed before any accusations are made.","zh-TW":"在提出任何指控之前需要有確鑿的證據。"},{"en":"Competition followed hard on the heels of the product launch.","zh-TW":"競爭緊隨產品發布而來。"}]', '{"adverb":"hardly","noun":"hardship"}', 'hard 作副詞意為「努力地/猛烈地」（不可用 hardly 替換，hardly = 幾乎不），hard evidence = 確鑿證據，hard currency = 硬通貨，均是 TOEIC 商業報告的重要詞彙。', 1, 3198, NULL),
(3199, 'hard copy', '/hɑːrd ˈkɒpi/', 'noun', '{"zh-TW":["紙本文件；書面副本"],"en":["a physical printed version of a digital document"]}', NULL, 'provide a hard copy / request a hard copy', '[{"en":"Please submit both digital and hard copy versions of the form.","zh-TW":"請提交表格的數位和紙本版本。"},{"en":"The contract must be signed in hard copy for legal validity.","zh-TW":"合約必須以書面形式簽署以具有法律效力。"}]', '{"opposite":"soft copy"}', NULL, 3, 3199, NULL);